function validate([s, k]) {
  if (!Number.isInteger(k) || k < 4 || k > 26) return 'k is between 4 and 26.';
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 letters.';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i) - 97;
    if (code < 0 || code >= k) return 's uses only the first k lowercase letters.';
    if (i >= 1 && s[i] === s[i - 1]) return 's must be beautiful: no two equal neighbours.';
    if (i >= 2 && s[i] === s[i - 2]) return 's must be beautiful: no palindrome of length 3.';
  }
  return null;
}

