function smallestBeautifulString(s, k) {
  const chars = [...s].map(ch => ch.charCodeAt(0) - 97);
  const n = chars.length;
  const fits = (index, letter) =>
    (index < 1 || chars[index - 1] !== letter) && (index < 2 || chars[index - 2] !== letter);

  for (let i = n - 1; i >= 0; i--) {
    for (let letter = chars[i] + 1; letter < k; letter++) {
      if (!fits(i, letter)) {
        continue;
      }
      chars[i] = letter;
      for (let j = i + 1; j < n; j++) {
        let smallest = 0;
        while (!fits(j, smallest)) {
          smallest++;
        }
        chars[j] = smallest;
      }
      return chars.map(code => String.fromCharCode(97 + code)).join('');
    }
  }
  return '';
}

