function smallestBeautifulString(s, k) {
  // Depth-first search over strings in dictionary order, dropping any prefix that already
  // contains a palindrome (checked against every substring, without the length 2/3 shortcut).
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, k);
  const built = [];
  const endsInPalindrome = () => {
    for (let start = 0; start < built.length - 1; start++) {
      const piece = built.slice(start).join('');
      if (piece === [...piece].reverse().join('')) return true;
    }
    return false;
  };
  const search = (tight) => {
    if (built.length === s.length) return !tight;
    const from = tight ? letters.indexOf(s[built.length]) : 0;
    for (let i = from; i < k; i++) {
      built.push(letters[i]);
      if (!endsInPalindrome() && search(tight && i === from)) return true;
      built.pop();
    }
    return false;
  };
  return search(true) ? built.join('') : '';
}

