function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(5000, 10000) : int(1, 7);
  const k = large ? (rand() < 0.5 ? 26 : int(4, 26)) : (rand() < 0.6 ? int(4, 5) : int(4, 26));
  // Up to cut the letters are random; after it each letter is the largest allowed one,
  // which forces the answer to change an earlier position (or not exist at all).
  const cut = rand() < 0.3 ? n : rand() < 0.3 ? 0 : int(0, n);
  const chars = [];
  for (let i = 0; i < n; i++) {
    const allowed = [];
    for (let letter = 0; letter < k; letter++) {
      if (letter !== chars[i - 1] && letter !== chars[i - 2]) allowed.push(letter);
    }
    chars.push(i < cut ? allowed[Math.floor(rand() * allowed.length)] : allowed[allowed.length - 1 - (rand() < 0.1 ? 1 : 0)]);
  }
  return [chars.map(code => String.fromCharCode(97 + code)).join(''), k];
}
